prelude:
// Force-included into every program Xenon builds with MSVC.
// It makes crashes and debug checks print a plain message to stderr instead of opening a dialog box
// that would freeze the program while it waits for a click nobody can make.
#pragma once
#if defined(_MSC_VER) && defined(__cplusplus)
#include <crtdbg.h>
#include <exception>
#include <stdio.h>
#include <stdlib.h>

extern "C" __declspec(dllimport) unsigned int __stdcall SetErrorMode(unsigned int);

namespace xenon_detail
{
    // Says what went wrong when an exception is never caught, instead of dying silently.
    [[noreturn]] inline void onTerminate() noexcept
    {
        if (std::exception_ptr current{ std::current_exception() })
        {
            try { std::rethrow_exception(current); }
            catch (const std::exception& e) { fprintf(stderr, "Uncaught exception: %s\n", e.what()); }
            catch (...) { fputs("Uncaught exception: (not derived from std::exception)\n", stderr); }
        }
        else fputs("std::terminate() was called.\n", stderr);
        fflush(stderr);
        abort();
    }

    struct QuietRuntime
    {
        QuietRuntime()
        {
            std::set_terminate(&onTerminate);
            SetErrorMode(0x0001u | 0x0002u | 0x8000u);   // no critical-error, GP-fault or open-file boxes
            _set_abort_behavior(0, _WRITE_ABORT_MSG | _CALL_REPORTFAULT);
#ifdef _DEBUG
            _CrtSetReportMode(_CRT_WARN, _CRTDBG_MODE_FILE);
            _CrtSetReportFile(_CRT_WARN, _CRTDBG_FILE_STDERR);
            _CrtSetReportMode(_CRT_ERROR, _CRTDBG_MODE_FILE);
            _CrtSetReportFile(_CRT_ERROR, _CRTDBG_FILE_STDERR);
            _CrtSetReportMode(_CRT_ASSERT, _CRTDBG_MODE_FILE);
            _CrtSetReportFile(_CRT_ASSERT, _CRTDBG_FILE_STDERR);
#endif
        }
    };
    inline QuietRuntime quietRuntime{};
}
#endif

testHeader:
// A tiny unit-test kit used when a task asks for functions or classes instead of a whole program.
//   TEST("name") { CHECK(cond); CHECK_EQ(actual, expected); CHECK_NEAR(a, b, 0.001); CHECK_THROWS(expr); }
//   xenon::output_of([&]{ ... })            -> everything the code printed to std::cout
//   xenon::run_with_input("5 7\n", [&]{..}) -> same, with std::cin fed from the given text
// Results go to a file (argv[1]) so that redirecting std::cout inside a test cannot hide them.
#pragma once
#if defined(_MSC_VER)
#include <crtdbg.h>
#endif
#include <array>
#include <cmath>
#include <cstdio>
#include <exception>
#include <functional>
#include <iostream>
#include <memory>
#include <sstream>
#include <stdexcept>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

namespace xenon
{
    struct Case { const char* name; void (*fn)(); };
    inline std::vector<Case>& cases() { static std::vector<Case> all; return all; }
    struct Register { Register(const char* name, void (*fn)()) { cases().push_back({ name, fn }); } };

    inline int& failures() { static int n{ 0 }; return n; }
    inline std::string& messages() { static std::string m; return m; }

    inline void fail(const std::string& message, int line)
    {
        ++failures();
        if (!messages().empty()) messages() += "\n";
        messages() += message + "  (test line " + std::to_string(line) + ")";
    }

    template <typename T>
    concept Streamable = requires(std::ostream& out, const T& value) { out << value; };

    template <typename T>
    concept Iterable = requires(const T& value) { value.begin(); value.end(); } && !std::is_convertible_v<T, std::string_view>;

    template <typename T>
    std::string show(const T& value)
    {
        if constexpr (std::is_same_v<T, bool>) return value ? "true" : "false";
        else if constexpr (std::is_same_v<T, char>) return std::string("'") + value + "'";
        else if constexpr (std::is_convertible_v<T, std::string_view>)
        {
            std::string text{ std::string_view{ value } };
            std::string shown{ "\"" };
            for (char c : text) { if (c == '\n') shown += "\\n"; else if (c == '\t') shown += "\\t"; else shown += c; }
            return shown + "\"";
        }
        else if constexpr (Iterable<T>)
        {
            std::string shown{ "[" };
            bool first{ true };
            for (const auto& item : value) { if (!first) shown += ", "; shown += show(item); first = false; }
            return shown + "]";
        }
        else if constexpr (std::is_enum_v<T>) return std::to_string(static_cast<long long>(value));
        else if constexpr (Streamable<T>) { std::ostringstream out; out << value; return out.str(); }
        else return "<value>";
    }

    template <typename A, typename B>
    void check_eq(const A& actual, const B& expected, const char* expr, int line)
    {
#pragma warning(push)
#pragma warning(disable: 4388 4389 4018 4244 4267 4305)
        const bool same{ actual == expected };
#pragma warning(pop)
        if (!same) fail(std::string(expr) + " gave " + show(actual) + ", expected " + show(expected), line);
    }

    inline void check_near(double actual, double expected, double eps, const char* expr, int line)
    {
        if (!(std::fabs(actual - expected) <= eps))
            fail(std::string(expr) + " gave " + show(actual) + ", expected about " + show(expected), line);
    }

    template <typename F>
    std::string output_of(F&& body)
    {
        std::ostringstream captured;
        std::streambuf* old{ std::cout.rdbuf(captured.rdbuf()) };
        try { body(); }
        catch (...) { std::cout.rdbuf(old); throw; }
        std::cout.rdbuf(old);
        return captured.str();
    }

    template <typename F>
    std::string run_with_input(const std::string& input, F&& body)
    {
        std::istringstream fake{ input };
        std::streambuf* old{ std::cin.rdbuf(fake.rdbuf()) };
        std::cin.clear();
        std::string printed;
        try { printed = output_of(body); }
        catch (...) { std::cin.rdbuf(old); std::cin.clear(); throw; }
        std::cin.rdbuf(old);
        std::cin.clear();
        return printed;
    }

    /// Remembers how much heap memory is in use, so a test can tell whether some code leaked.
    /// Works with the MSVC debug runtime; elsewhere it reports no leaks.
    struct HeapMark
    {
#if defined(_MSC_VER) && defined(_DEBUG)
        _CrtMemState before{};
        HeapMark() { _CrtMemCheckpoint(&before); }
        long long leakedBytes() const
        {
            _CrtMemState now{}, diff{};
            _CrtMemCheckpoint(&now);
            if (_CrtMemDifference(&diff, &before, &now)) return static_cast<long long>(diff.lSizes[_NORMAL_BLOCK]);
            return 0;
        }
#else
        long long leakedBytes() const { return 0; }
#endif
    };

    /// Removes trailing spaces on each line and trailing blank lines, so layout slips do not fail a test.
    inline std::string tidy(const std::string& text)
    {
        std::string out, line;
        std::istringstream in{ text };
        std::vector<std::string> lines;
        while (std::getline(in, line))
        {
            while (!line.empty() && (line.back() == ' ' || line.back() == '\t' || line.back() == '\r')) line.pop_back();
            lines.push_back(line);
        }
        while (!lines.empty() && lines.back().empty()) lines.pop_back();
        for (std::size_t i{ 0 }; i < lines.size(); ++i) { if (i) out += '\n'; out += lines[i]; }
        return out;
    }

    inline std::string escape(const std::string& text)
    {
        std::string out;
        for (char c : text) { if (c == '\n') out += "\\n"; else if (c == '\t') out += "\\t"; else if (c == '\r') continue; else out += c; }
        return out;
    }

    inline int run_all(int argc, char** argv)
    {
        std::FILE* report{ nullptr };
        if (argc > 1) report = std::fopen(argv[1], "w");
        if (!report) report = stderr;
        int failedCases{ 0 };
        for (const Case& c : cases())
        {
            std::fprintf(report, "B\t%s\n", c.name);
            std::fflush(report);
            failures() = 0;
            messages().clear();
            try { c.fn(); }
            catch (const std::exception& e) { fail(std::string("an exception escaped: ") + e.what(), 0); }
            catch (...) { fail("an unknown exception escaped", 0); }
            if (failures() == 0) std::fprintf(report, "P\t%s\n", c.name);
            else { ++failedCases; std::fprintf(report, "F\t%s\t%s\n", c.name, escape(messages()).c_str()); }
            std::fflush(report);
        }
        std::fprintf(report, "E\t%d\n", failedCases);
        if (report != stderr) std::fclose(report);
        return failedCases == 0 ? 0 : 1;
    }
}

#define XENON_CAT2(a, b) a##b
#define XENON_CAT(a, b) XENON_CAT2(a, b)
#define TEST(name) \
    static void XENON_CAT(xenon_case_, __LINE__)(); \
    static xenon::Register XENON_CAT(xenon_reg_, __LINE__){ name, &XENON_CAT(xenon_case_, __LINE__) }; \
    static void XENON_CAT(xenon_case_, __LINE__)()

// Variadic so that commas inside braces, as in CHECK(Vec2{ 1, 2 } == v), do not split the argument.
#define CHECK(...) do { if (!(__VA_ARGS__)) xenon::fail("CHECK(" #__VA_ARGS__ ") was false", __LINE__); } while (false)
#define CHECK_EQ(actual, expected) xenon::check_eq((actual), (expected), #actual, __LINE__)
#define CHECK_NEAR(actual, expected, eps) xenon::check_near(static_cast<double>(actual), static_cast<double>(expected), (eps), #actual, __LINE__)
#define CHECK_OUTPUT(expression, expected) xenon::check_eq(xenon::tidy(xenon::output_of([&] { expression; })), xenon::tidy(expected), #expression " printed", __LINE__)
#define CHECK_THROWS(expression) do { bool xenon_threw{ false }; try { (void)(expression); } catch (...) { xenon_threw = true; } \
    if (!xenon_threw) xenon::fail(#expression " should have thrown an exception", __LINE__); } while (false)
#define CHECK_THROWS_AS(expression, type) do { bool xenon_threw{ false }; try { (void)(expression); } catch (const type&) { xenon_threw = true; } catch (...) {} \
    if (!xenon_threw) xenon::fail(#expression " should have thrown " #type, __LINE__); } while (false)
// Runs the statements and fails if heap memory allocated inside them was never freed.
#define CHECK_NO_LEAK(...) do { const xenon::HeapMark xenon_mark{}; { __VA_ARGS__; } const long long xenon_leaked{ xenon_mark.leakedBytes() }; \
    if (xenon_leaked > 0) xenon::fail("memory leak: " + std::to_string(xenon_leaked) + " bytes were allocated and never freed", __LINE__); } while (false)
#define CHECK_NOTHROW(expression) do { try { (void)(expression); } catch (...) { xenon::fail(#expression " threw an exception", __LINE__); } } while (false)

kits.python:
# Xenon's runner for Python on the website. Compiler Explorer runs this file; the learner's files sit next to it.
# It does one of three jobs, chosen by XENON (set on the first line when the site sends it):
#   "check"  compile every .py file and report syntax errors, without running anything
#   "run"    run the entry file like `python main.py`; with "interactive", stop and say so when input runs out
#   "unit"   load the solution file, then run the tests written against it and report each one
# Reports and errors use simple text lines the website reads; nothing here is shown to the learner as-is.
import builtins, io, os, sys, traceback

MARK_INPUT = "<<" + "xenon:needs-input" + ">>"
MARK_SYNTAX = "<<" + "xenon:syntax" + ">>"
USER = set()      # the learner's .py files; main() fills it in from what the website sent


def _syntax_errors():
    found = []
    for name in sorted(USER):
        try:
            with open(name, encoding="utf-8") as fh:
                compile(fh.read(), name, "exec")
        except SyntaxError as e:
            col = e.offset or 1
            found.append(f"{name}:{e.lineno or 1}:{col}: error: {type(e).__name__}: {e.msg}")
    return found


def _stop_for_input():
    sys.stdout.flush()
    sys.stdout.write(MARK_INPUT)
    sys.stdout.flush()
    sys.stderr.flush()
    os._exit(0)


class _WaitingStdin(io.TextIOBase):
    """Standard input that, when it runs dry, says the program wants more instead of reporting end of input."""
    def __init__(self, inner):
        self._inner = inner
    def readable(self):
        return True
    def readline(self, size=-1):
        line = self._inner.readline()
        if line == "":
            _stop_for_input()
        return line
    def read(self, size=-1):
        if size is None or size < 0:
            _stop_for_input()
        data = self._inner.read(size)
        if data == "":
            _stop_for_input()
        return data
    def __iter__(self):
        return self
    def __next__(self):
        return self.readline()
    @property
    def encoding(self):
        return "utf-8"


def _install_waiting_input():
    sys.stdin = _WaitingStdin(sys.stdin)
    real_input = builtins.input

    def waiting_input(prompt=""):
        try:
            return real_input(prompt)
        except EOFError:
            _stop_for_input()
    builtins.input = waiting_input


def _print_traceback(exc):
    # Only the learner's own frames: not this runner, not runpy.
    tb = traceback.TracebackException.from_exception(exc)
    keep = [f for f in tb.stack if os.path.basename(f.filename) in USER or f.filename == "the tests"]
    tb.stack = traceback.StackSummary.from_list(keep)
    text = "".join(tb.format())
    sys.stderr.write(text.replace(os.getcwd() + os.sep, "").replace(os.getcwd() + "/", ""))


def _run(entry, interactive, args):
    import runpy
    if interactive:
        _install_waiting_input()
    sys.argv = [entry] + list(args)
    sys.path.insert(0, os.getcwd())
    try:
        runpy.run_path(entry, run_name="__main__")
    except SystemExit:
        raise
    except BaseException as exc:
        sys.stdout.flush()
        _print_traceback(exc)
        sys.exit(1)


# ---------------------------------------------------------------- the test kit
_REPORT = sys.stderr
_tests = []
_failures = []


def _esc(text):
    return str(text).replace("\\", "\\\\").replace("\n", "\\n").replace("\t", "\\t")


def _test_line():
    for frame in reversed(traceback.extract_stack()):
        if frame.filename == "the tests":
            return frame.lineno
    return None


def _fail(message):
    line = _test_line()
    _failures.append(message + (f" (line {line})" if line else ""))


def _show(value):
    return repr(value)


def test(name):
    """@test("what it checks") above a function with checks in it."""
    def register(fn):
        _tests.append((name, fn))
        return fn
    return register


def check(condition, message=None):
    if not condition:
        _fail(message or "check(...) was false")


def check_eq(actual, expected):
    if isinstance(expected, float) or isinstance(actual, float):
        try:
            if abs(float(actual) - float(expected)) <= 1e-9 * max(1.0, abs(float(expected))):
                return
        except (TypeError, ValueError):
            pass
    if actual != expected:
        _fail(f"gave {_show(actual)}, expected {_show(expected)}")


def check_near(actual, expected, eps=1e-6):
    try:
        ok = abs(actual - expected) <= eps
    except TypeError:
        ok = False
    if not ok:
        _fail(f"gave {_show(actual)}, expected about {_show(expected)}")


def check_raises(kind, fn, *args, **kwargs):
    try:
        fn(*args, **kwargs)
    except kind:
        return
    except BaseException as e:
        _fail(f"raised {type(e).__name__}, expected {kind.__name__}")
        return
    _fail(f"did not raise {kind.__name__}")


def check_output(fn, expected):
    """Runs fn() and compares what it printed."""
    buf = io.StringIO()
    old = sys.stdout
    sys.stdout = buf
    try:
        fn()
    finally:
        sys.stdout = old
    tidy = lambda s: "\n".join(l.rstrip() for l in str(s).replace("\r\n", "\n").split("\n")).rstrip("\n")
    if tidy(buf.getvalue()) != tidy(expected):
        _fail(f"printed {_show(tidy(buf.getvalue()))}, expected {_show(tidy(expected))}")


def _unit(entry, tests_file):
    import runpy
    sys.path.insert(0, os.getcwd())
    ns = runpy.run_path(entry, run_name="solution")
    kit = {k: globals()[k] for k in ("test", "check", "check_eq", "check_near", "check_raises", "check_output")}
    ns.update(kit)
    with open(tests_file, encoding="utf-8") as fh:
        source = fh.read()
    exec(compile(source, "the tests", "exec"), ns)
    # Plain pytest-style functions count too: def test_something(): assert ...
    for name, value in list(ns.items()):
        if name.startswith("test_") and callable(value) and all(fn is not value for _, fn in _tests):
            _tests.append((name[5:].replace("_", " "), value))
    failed = 0
    for name, fn in _tests:
        _REPORT.write(f"B\t{_esc(name)}\n")
        _REPORT.flush()
        del _failures[:]
        try:
            fn()
        except AssertionError as e:
            line = None
            for frame in traceback.extract_tb(e.__traceback__):
                if frame.filename == "the tests":
                    line = frame.lineno
            what = str(e) or "an assert was false"
            _failures.append(what + (f" (line {line})" if line else ""))
        except BaseException as e:
            where = ""
            for frame in traceback.extract_tb(e.__traceback__):
                if os.path.basename(frame.filename) in USER:
                    where = f" in {os.path.basename(frame.filename)} line {frame.lineno}"
            _failures.append(f"raised {type(e).__name__}: {e}{where}")
        if _failures:
            failed += 1
            _REPORT.write(f"F\t{_esc(name)}\t{_esc('; '.join(_failures))}\n")
        else:
            _REPORT.write(f"P\t{_esc(name)}\n")
        _REPORT.flush()
    _REPORT.write(f"E\t{failed}\n")
    _REPORT.flush()


def main(job):
    USER.update(job.get("files", []))
    errors = _syntax_errors()
    if job["mode"] != "run" or errors:
        if errors:
            sys.stdout.write(MARK_SYNTAX + "\n" + "\n".join(errors) + "\n")
            sys.exit(3)
        if job["mode"] == "check":
            return
    if job["mode"] == "unit":
        _unit(job["entry"], job["tests"])
    else:
        _run(job["entry"], job.get("interactive", False), job.get("args", []))

kits.csharpKit:
// Xenon's test kit for C#. The website appends this to a unit-test build; tests call Test, Check, CheckEq and friends
// directly (the build adds "global using static XenonKit;"). Results go to standard error, one line per event:
// B name / P name / F name message / E failures, the same report the C++ kit writes.
static class XenonKit
{
    static readonly System.Collections.Generic.List<string> failures = new();
    static int failedTests;

    static string Esc(string s) => s.Replace("\\", "\\\\").Replace("\n", "\\n").Replace("\t", "\\t");

    public static string Show(object? value)
    {
        if (value is null) return "null";
        if (value is string s) return "\"" + s + "\"";
        if (value is char c) return "'" + c + "'";
        if (value is bool b) return b ? "true" : "false";
        if (value is double d) return d.ToString("R", System.Globalization.CultureInfo.InvariantCulture);
        if (value is float f) return f.ToString("R", System.Globalization.CultureInfo.InvariantCulture);
        if (value is System.Collections.IDictionary dict)
        {
            var parts = new System.Collections.Generic.List<string>();
            foreach (System.Collections.DictionaryEntry e in dict) parts.Add(Show(e.Key) + ": " + Show(e.Value));
            return "{ " + string.Join(", ", parts) + " }";
        }
        if (value is System.Collections.IEnumerable items)
        {
            var parts = new System.Collections.Generic.List<string>();
            foreach (var item in items) parts.Add(Show(item));
            return "[" + string.Join(", ", parts) + "]";
        }
        return System.Convert.ToString(value, System.Globalization.CultureInfo.InvariantCulture) ?? "?";
    }

    static void Fail(string message, int line) => failures.Add(line > 0 ? $"{message} (line {line})" : message);

    static bool Same(object? a, object? b)
    {
        if (a is null || b is null) return a is null && b is null;
        if (a is string || b is string) return Equals(a, b);
        if (a is System.Collections.IEnumerable x && b is System.Collections.IEnumerable y)
        {
            var ex = x.GetEnumerator(); var ey = y.GetEnumerator();
            while (true)
            {
                bool mx = ex.MoveNext(), my = ey.MoveNext();
                if (mx != my) return false;
                if (!mx) return true;
                if (!Same(ex.Current, ey.Current)) return false;
            }
        }
        if (IsNumber(a) && IsNumber(b))
        {
            if (a is double or float or decimal || b is double or float or decimal)
                return System.Math.Abs(System.Convert.ToDouble(a) - System.Convert.ToDouble(b)) <= 1e-9 * System.Math.Max(1.0, System.Math.Abs(System.Convert.ToDouble(b)));
            return System.Convert.ToDecimal(a) == System.Convert.ToDecimal(b);
        }
        return Equals(a, b);
    }

    static bool IsNumber(object o) => o is sbyte or byte or short or ushort or int or uint or long or ulong or float or double or decimal;

    public static void Test(string name, System.Action body)
    {
        System.Console.Out.Flush();
        System.Console.Error.WriteLine($"B\t{Esc(name)}");
        failures.Clear();
        try { body(); }
        catch (System.Exception e) { failures.Add($"threw {e.GetType().Name}: {e.Message}{Where(e)}"); }
        System.Console.Out.Flush();
        if (failures.Count == 0) System.Console.Error.WriteLine($"P\t{Esc(name)}");
        else { failedTests++; System.Console.Error.WriteLine($"F\t{Esc(name)}\t{Esc(string.Join("; ", failures))}"); }
    }

    static string Where(System.Exception e)
    {
        var trace = new System.Diagnostics.StackTrace(e, true);
        foreach (var frame in trace.GetFrames())
        {
            var file = frame.GetFileName();
            if (file != null && frame.GetFileLineNumber() > 0 && !file.EndsWith("the tests"))
                return $" in {System.IO.Path.GetFileName(file)} line {frame.GetFileLineNumber()}";
        }
        return "";
    }

    public static void Check(bool condition,
        [System.Runtime.CompilerServices.CallerArgumentExpression(nameof(condition))] string? expr = null,
        [System.Runtime.CompilerServices.CallerLineNumber] int line = 0)
    {
        if (!condition) Fail($"Check({expr}) was false", line);
    }

    public static void CheckEq<T>(T actual, T expected,
        [System.Runtime.CompilerServices.CallerArgumentExpression(nameof(actual))] string? expr = null,
        [System.Runtime.CompilerServices.CallerLineNumber] int line = 0)
    {
        if (!Same(actual, expected)) Fail($"{expr} gave {Show(actual)}, expected {Show(expected)}", line);
    }

    public static void CheckEq<T>(System.Collections.Generic.IEnumerable<T> actual, System.Collections.Generic.IEnumerable<T> expected,
        [System.Runtime.CompilerServices.CallerArgumentExpression(nameof(actual))] string? expr = null,
        [System.Runtime.CompilerServices.CallerLineNumber] int line = 0)
    {
        if (!Same(actual, expected)) Fail($"{expr} gave {Show(actual)}, expected {Show(expected)}", line);
    }

    public static void CheckNear(double actual, double expected, double eps = 1e-6,
        [System.Runtime.CompilerServices.CallerArgumentExpression(nameof(actual))] string? expr = null,
        [System.Runtime.CompilerServices.CallerLineNumber] int line = 0)
    {
        if (!(System.Math.Abs(actual - expected) <= eps)) Fail($"{expr} gave {Show(actual)}, expected about {Show(expected)}", line);
    }

    public static void CheckThrows<TException>(System.Action body,
        [System.Runtime.CompilerServices.CallerArgumentExpression(nameof(body))] string? expr = null,
        [System.Runtime.CompilerServices.CallerLineNumber] int line = 0) where TException : System.Exception
    {
        try { body(); }
        catch (TException) { return; }
        catch (System.Exception e) { Fail($"{expr} threw {e.GetType().Name}, expected {typeof(TException).Name}", line); return; }
        Fail($"{expr} did not throw {typeof(TException).Name}", line);
    }

    public static void CheckOutput(System.Action body, string expected,
        [System.Runtime.CompilerServices.CallerArgumentExpression(nameof(body))] string? expr = null,
        [System.Runtime.CompilerServices.CallerLineNumber] int line = 0)
    {
        var old = System.Console.Out;
        var buffer = new System.IO.StringWriter();
        System.Console.SetOut(buffer);
        try { body(); } finally { System.Console.SetOut(old); }
        static string Tidy(string s) => string.Join("\n", s.Replace("\r\n", "\n").Split('\n').Select(l => l.TrimEnd())).TrimEnd('\n');
        if (Tidy(buffer.ToString()) != Tidy(expected)) Fail($"{expr} printed {Show(Tidy(buffer.ToString()))}, expected {Show(Tidy(expected))}", line);
    }

    public static void Finish()
    {
        System.Console.Out.Flush();
        System.Console.Error.WriteLine($"E\t{failedTests}");
        System.Console.Error.Flush();
    }
}

