// Xenon's test kit for Java. The website's test class extends XenonKit, so tests call test(), check(), checkEq()
// directly. Results go to standard error, one line per event: B name / P name / F name message / E failures,
// the same report the C++ kit writes.
class XenonKit {
    interface Body { void run() throws Throwable; }

    // The tests start on this line of the generated test file; the website sets it.
    static int firstLine = 2;
    private static final java.util.List<String> failures = new java.util.ArrayList<>();
    private static int failedTests = 0;

    private static String esc(String s) { return s.replace("\\", "\\\\").replace("\n", "\\n").replace("\t", "\\t"); }

    static String show(Object v) {
        if (v == null) return "null";
        if (v instanceof String s) return "\"" + s + "\"";
        if (v instanceof Character c) return "'" + c + "'";
        if (v.getClass().isArray()) {
            if (v instanceof Object[] a) return java.util.Arrays.deepToString(a);
            if (v instanceof int[] a) return java.util.Arrays.toString(a);
            if (v instanceof long[] a) return java.util.Arrays.toString(a);
            if (v instanceof double[] a) return java.util.Arrays.toString(a);
            if (v instanceof char[] a) return java.util.Arrays.toString(a);
            if (v instanceof boolean[] a) return java.util.Arrays.toString(a);
            if (v instanceof byte[] a) return java.util.Arrays.toString(a);
            if (v instanceof short[] a) return java.util.Arrays.toString(a);
            if (v instanceof float[] a) return java.util.Arrays.toString(a);
        }
        return String.valueOf(v);
    }

    private static int testLine() {
        for (StackTraceElement e : new Throwable().getStackTrace())
            if ("XenonTests".equals(e.getClassName()) || e.getClassName().startsWith("XenonTests$")) return e.getLineNumber() - firstLine + 1;
        return -1;
    }

    private static void fail(String message) {
        int line = testLine();
        failures.add(line > 0 ? message + " (line " + line + ")" : message);
    }

    private static boolean same(Object a, Object b) {
        if (a == null || b == null) return a == b;
        if (a instanceof Number x && b instanceof Number y) {
            boolean decimal = a instanceof Double || a instanceof Float || b instanceof Double || b instanceof Float;
            if (decimal) return Math.abs(x.doubleValue() - y.doubleValue()) <= 1e-9 * Math.max(1.0, Math.abs(y.doubleValue()));
            return x.longValue() == y.longValue();
        }
        if (a.getClass().isArray() && b.getClass().isArray()) return java.util.Objects.deepEquals(a, b);
        if (a instanceof java.util.List<?> x && b.getClass().isArray() && b instanceof Object[] y) return x.equals(java.util.Arrays.asList(y));
        return a.equals(b);
    }

    static void test(String name, Body body) {
        System.out.flush();
        System.err.println("B\t" + esc(name));
        failures.clear();
        try { body.run(); }
        catch (Throwable t) {
            String where = "";
            for (StackTraceElement e : t.getStackTrace()) {
                String file = e.getFileName();
                if (file != null && !file.startsWith("XenonKit") && !e.getClassName().startsWith("XenonTests") && e.getLineNumber() > 0) { where = " in " + file + " line " + e.getLineNumber(); break; }
            }
            failures.add("threw " + t.getClass().getSimpleName() + (t.getMessage() != null ? ": " + t.getMessage() : "") + where);
        }
        System.out.flush();
        if (failures.isEmpty()) System.err.println("P\t" + esc(name));
        else { failedTests++; System.err.println("F\t" + esc(name) + "\t" + esc(String.join("; ", failures))); }
    }

    static void check(boolean condition) { if (!condition) fail("check(...) was false"); }
    static void check(boolean condition, String message) { if (!condition) fail(message); }

    static void checkEq(Object actual, Object expected) {
        if (!same(actual, expected)) fail("gave " + show(actual) + ", expected " + show(expected));
    }

    static void checkNear(double actual, double expected, double eps) {
        if (!(Math.abs(actual - expected) <= eps)) fail("gave " + actual + ", expected about " + expected);
    }

    static void checkNear(double actual, double expected) { checkNear(actual, expected, 1e-6); }

    static void checkThrows(Class<? extends Throwable> kind, Body body) {
        try { body.run(); }
        catch (Throwable t) {
            if (kind.isInstance(t)) return;
            fail("threw " + t.getClass().getSimpleName() + ", expected " + kind.getSimpleName());
            return;
        }
        fail("did not throw " + kind.getSimpleName());
    }

    static void checkOutput(Body body, String expected) {
        java.io.PrintStream old = System.out;
        java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();
        System.setOut(new java.io.PrintStream(buffer, true));
        try { body.run(); } catch (Throwable t) { System.setOut(old); fail("threw " + t.getClass().getSimpleName()); return; }
        finally { System.setOut(old); }
        String got = tidy(buffer.toString()), want = tidy(expected);
        if (!got.equals(want)) fail("printed " + show(got) + ", expected " + show(want));
    }

    private static String tidy(String s) {
        String[] lines = s.replace("\r\n", "\n").split("\n", -1);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < lines.length; i++) { if (i > 0) out.append('\n'); out.append(lines[i].replaceAll("[ \\t]+$", "")); }
        return out.toString().replaceAll("\n+$", "");
    }

    static void finish() {
        System.out.flush();
        System.err.println("E\t" + failedTests);
        System.err.flush();
    }
}

