kits.rustKit:
// Xenon's test kit for Rust. The website includes this into the test build with include!, so tests call test(),
// check(), check_eq() directly. Results go to standard error, one line per event: B name / P name / F name message /
// E failures, the same report the C++ kit writes.
#[allow(dead_code)]
mod xenon_kit {
    use std::cell::RefCell;
    use std::fmt::Debug;

    thread_local! {
        static FAILURES: RefCell<Vec<String>> = RefCell::new(Vec::new());
        static PANIC: RefCell<Option<String>> = RefCell::new(None);
    }
    static FAILED: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

    fn esc(s: &str) -> String { s.replace('\\', "\\\\").replace('\n', "\\n").replace('\t', "\\t") }

    fn fail(message: String, line: u32) {
        let at = if line >= super::XENON_FIRST_LINE { format!(" (line {})", line - super::XENON_FIRST_LINE + 1) } else { String::new() };
        FAILURES.with(|f| f.borrow_mut().push(format!("{}{}", message, at)));
    }

    pub fn begin() {
        std::panic::set_hook(Box::new(|info| {
            let msg = if let Some(s) = info.payload().downcast_ref::<&str>() { s.to_string() }
                else if let Some(s) = info.payload().downcast_ref::<String>() { s.clone() }
                else { "panic".to_string() };
            let at = info.location().map(|l| {
                let file = l.file().rsplit(['/', '\\']).next().unwrap_or(l.file()).to_string();
                if file == "example.rs" || file == "<source>" { String::new() } else { format!(" in {} line {}", file, l.line()) }
            }).unwrap_or_default();
            PANIC.with(|p| *p.borrow_mut() = Some(format!("panicked: {}{}", msg, at)));
        }));
    }

    pub fn test<F: FnOnce()>(name: &str, body: F) {
        use std::io::Write;
        let _ = std::io::stdout().flush();
        eprintln!("B\t{}", esc(name));
        FAILURES.with(|f| f.borrow_mut().clear());
        PANIC.with(|p| *p.borrow_mut() = None);
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(body));
        if result.is_err() {
            let why = PANIC.with(|p| p.borrow_mut().take()).unwrap_or_else(|| "panicked".to_string());
            FAILURES.with(|f| f.borrow_mut().push(why));
        }
        let _ = std::io::stdout().flush();
        let failures = FAILURES.with(|f| f.borrow().clone());
        if failures.is_empty() { eprintln!("P\t{}", esc(name)); }
        else { FAILED.fetch_add(1, std::sync::atomic::Ordering::Relaxed); eprintln!("F\t{}\t{}", esc(name), esc(&failures.join("; "))); }
    }

    #[track_caller]
    pub fn check(condition: bool) {
        if !condition { fail("check(...) was false".to_string(), std::panic::Location::caller().line()); }
    }

    #[track_caller]
    pub fn check_eq<A: PartialEq<B> + Debug, B: Debug>(actual: A, expected: B) {
        if actual != expected { fail(format!("gave {:?}, expected {:?}", actual, expected), std::panic::Location::caller().line()); }
    }

    #[track_caller]
    pub fn check_near(actual: f64, expected: f64, eps: f64) {
        if !((actual - expected).abs() <= eps) { fail(format!("gave {}, expected about {}", actual, expected), std::panic::Location::caller().line()); }
    }

    #[track_caller]
    pub fn check_panics<F: FnOnce()>(body: F) {
        let line = std::panic::Location::caller().line();
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(body));
        PANIC.with(|p| *p.borrow_mut() = None);
        if result.is_ok() { fail("did not panic".to_string(), line); }
    }

    pub fn finish() {
        use std::io::Write;
        let _ = std::io::stdout().flush();
        eprintln!("E\t{}", FAILED.load(std::sync::atomic::Ordering::Relaxed));
    }
}
#[allow(unused_imports)]
use xenon_kit::{check, check_eq, check_near, check_panics, test};

kits.cTest:
/* Xenon's test kit for C. The website puts the practice tests inside main() after this header and the learner's
   solution, so a test reads like the C++ kit's:

       TEST("doubles a number") { CHECK_EQ(twice(21), 42); CHECK(twice(0) == 0); }

   Results go to standard error, one line per event: B name / P name / F name message / E failures, the same report
   every other language's kit writes. */
#ifndef XENON_TEST_C_H
#define XENON_TEST_C_H

#include <math.h>
#include <signal.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char *xenon_name = "";
static int xenon_fails = 0;
static int xenon_failed_cases = 0;
static char xenon_messages[1024];

static void xenon_note(const char *text)
{
    size_t used = strlen(xenon_messages);
    if (used && used + 2 < sizeof xenon_messages) { strcat(xenon_messages, "; "); used += 2; }
    if (used + 1 < sizeof xenon_messages) strncat(xenon_messages, text, sizeof xenon_messages - used - 1);
}

static void xenon_fail(const char *text, int line)
{
    char at[1100];
    xenon_fails++;
    if (xenon_fails > 3) return;                    /* the first few are enough to go on */
    snprintf(at, sizeof at, "%s (line %d)", text, line);
    for (char *c = at; *c; c++) if (*c == '\n' || *c == '\t') *c = ' ';
    xenon_note(at);
}

/* A crash inside a test is reported as that test failing, instead of ending the report without a word. */
static void xenon_crashed(int signal_number)
{
    const char *why = signal_number == SIGSEGV ? "crashed: it read or wrote memory it does not own (a bad pointer, or past the end of an array)"
                    : signal_number == SIGFPE ? "crashed: a whole number was divided by zero"
                    : "crashed: abort() was called (a failed assert, or a corrupted heap)";
    fflush(stdout);
    fprintf(stderr, "F\t%s\t%s\n", xenon_name, why);
    fprintf(stderr, "E\t%d\n", xenon_failed_cases + 1);
    fflush(stderr);
    _Exit(0);
}

static void xenon_start(void)
{
    signal(SIGSEGV, xenon_crashed);
    signal(SIGFPE, xenon_crashed);
    signal(SIGABRT, xenon_crashed);
}

static int xenon_begin(const char *name)
{
    fflush(stdout);
    fprintf(stderr, "B\t%s\n", name);
    xenon_name = name;
    xenon_fails = 0;
    xenon_messages[0] = '\0';
    return 1;
}

static int xenon_end(void)
{
    fflush(stdout);
    if (xenon_fails == 0) fprintf(stderr, "P\t%s\n", xenon_name);
    else { xenon_failed_cases++; fprintf(stderr, "F\t%s\t%s\n", xenon_name, xenon_messages); }
    return 0;
}

static int xenon_finish(void)
{
    fflush(stdout);
    fprintf(stderr, "E\t%d\n", xenon_failed_cases);
    return 0;
}

static void xenon_eq_int(long long actual, long long expected, const char *what, int line)
{
    char text[400];
    if (actual == expected) return;
    snprintf(text, sizeof text, "%s gave %lld, expected %lld", what, actual, expected);
    xenon_fail(text, line);
}

static void xenon_eq_uint(unsigned long long actual, unsigned long long expected, const char *what, int line)
{
    char text[400];
    if (actual == expected) return;
    snprintf(text, sizeof text, "%s gave %llu, expected %llu", what, actual, expected);
    xenon_fail(text, line);
}

static void xenon_eq_char(char actual, char expected, const char *what, int line)
{
    char text[400];
    if (actual == expected) return;
    snprintf(text, sizeof text, "%s gave '%c' (%d), expected '%c' (%d)", what, actual, actual, expected, expected);
    xenon_fail(text, line);
}

static void xenon_eq_double(double actual, double expected, const char *what, int line)
{
    char text[400];
    if (actual == expected || fabs(actual - expected) <= 1e-9 * fmax(1.0, fabs(expected))) return;
    snprintf(text, sizeof text, "%s gave %.10g, expected %.10g", what, actual, expected);
    xenon_fail(text, line);
}

static void xenon_eq_str(const char *actual, const char *expected, const char *what, int line)
{
    char text[600];
    if (actual && expected && strcmp(actual, expected) == 0) return;
    if (!actual) snprintf(text, sizeof text, "%s gave NULL, expected \"%.200s\"", what, expected ? expected : "(NULL)");
    else snprintf(text, sizeof text, "%s gave \"%.200s\", expected \"%.200s\"", what, actual, expected ? expected : "(NULL)");
    xenon_fail(text, line);
}

#define TEST(name) for (int xenon_once = xenon_begin(name); xenon_once; xenon_once = xenon_end())
#define CHECK(condition) do { if (!(condition)) xenon_fail("CHECK(" #condition ") was false", __LINE__); } while (0)
#define CHECK_EQ(actual, expected) _Generic((actual), \
    char *: xenon_eq_str, const char *: xenon_eq_str, \
    char: xenon_eq_char, \
    float: xenon_eq_double, double: xenon_eq_double, long double: xenon_eq_double, \
    unsigned int: xenon_eq_uint, unsigned long: xenon_eq_uint, unsigned long long: xenon_eq_uint, \
    default: xenon_eq_int)((actual), (expected), #actual, __LINE__)
#define CHECK_STR(actual, expected) xenon_eq_str((actual), (expected), #actual, __LINE__)
#define CHECK_NEAR(actual, expected, tolerance) do { double xenon_a = (double)(actual), xenon_e = (double)(expected); \
    if (fabs(xenon_a - xenon_e) > (tolerance)) { char xenon_t[400]; \
        snprintf(xenon_t, sizeof xenon_t, "%s gave %.10g, expected %.10g (give or take %g)", #actual, xenon_a, xenon_e, (double)(tolerance)); \
        xenon_fail(xenon_t, __LINE__); } } while (0)

#endif

kits.cInput:
/* Force-included (gcc -include) when the website runs a C program "interactively". Compiler Explorer runs a
   program from start to finish with all of its input given up front, so the website runs it again each time the
   learner types a line. This header swaps standard input for a stream that, when the input typed so far runs out,
   prints a marker and stops the program instead of reporting the end of the input. The website shows what was
   printed before the marker and waits for the next line. (glibc only: Compiler Explorer runs Linux.) */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <unistd.h>

static ssize_t xenon_input_read(void *cookie, char *buffer, size_t size)
{
    (void)cookie;
    ssize_t got = read(0, buffer, size);
    if (got == 0) {
        fflush(stdout);
        fputs("<<xenon:needs-input>>", stdout);
        fflush(stdout);
        _Exit(0);
    }
    return got;
}

__attribute__((constructor)) static void xenon_input_install(void)
{
    cookie_io_functions_t io = { .read = xenon_input_read };
    FILE *in = fopencookie(NULL, "r", io);
    if (in) stdin = in;
}
